#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    int l = 0, r = len - 1;
    while (l < r) {
        if (!isalnum(s[l])) l++;
        else if (!isalnum(s[r])) r--;
        else {
            char tmp = s[l]; s[l] = s[r]; s[r] = tmp;
            l++; r--;
        }
    }
    puts(s);
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <cctype>
using namespace std;
int main() {
    string s; if (!getline(cin, s)) return 0;
    int l = 0, r = (int)s.length() - 1;
    while (l < r) {
        if (!isalnum(s[l])) l++;
        else if (!isalnum(s[r])) r--;
        else {
            swap(s[l], s[r]);
            l++; r--;
        }
    }
    cout << s << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            char[] s = sc.nextLine().toCharArray();
            int l = 0, r = s.length - 1;
            while (l < r) {
                if (!Character.isLetterOrDigit(s[l])) l++;
                else if (!Character.isLetterOrDigit(s[r])) r--;
                else {
                    char tmp = s[l]; s[l] = s[r]; s[r] = tmp;
                    l++; r--;
                }
            }
            System.out.println(new String(s));
        }
    }
}

code.Python3:
import sys
def main():
    s = list(sys.stdin.read().strip())
    l, r = 0, len(s) - 1
    while l < r:
        if not s[l].isalnum(): l += 1
        elif not s[r].isalnum(): r -= 1
        else:
            s[l], s[r] = s[r], s[l]
            l += 1; r -= 1
    print("".join(s))
if __name__ == "__main__": main()

