const fs = require("fs");
function main() {
    const s = fs.readFileSync(0, "utf-8").trim().split("");
    let l = 0, r = s.length - 1;
    const isAlnum = c => /[a-zA-Z0-9]/.test(c);
    while (l < r) {
        if (!isAlnum(s[l])) l++;
        else if (!isAlnum(s[r])) r--;
        else {
            const tmp = s[l]; s[l] = s[r]; s[r] = tmp;
            l++; r--;
        }
    }
    console.log(s.join(""));
}
main();

